pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed param: an address (the fuzzer will supply many addresses)
    function testFuzz_property(address someCaller) public {
        // Keep domain wide but avoid the zero address for the caller to be realistic
        // (we don't want to constrain too much; zero is allowed but not necessary)
        // No vm.assume to keep it wide as required; we simply perform a call via try/catch.

        // Call owner() via an external call from arbitrary caller context.
        // The reference contract stores the deployer as owner (non-zero). The mutant returns address(0).
        bool ok;
        address got;
        try c.owner{gas: gasleft()}() returns (address a) {
            ok = true;
            got = a;
        } catch {
            ok = false;
            got = address(0);
        }

        // General rule (single assertion): the reference contract's owner() is always non-zero
        // for all inputs; the mutant will violate this by returning address(0) for some inputs.
        assertTrue(ok && got != address(0));
    }
}

